import java.math.*;
import java.nio.ByteOrder;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class BitInputStream_readBits_TriageGen0Test {

    private static final int MAXIMUM_CACHE_SIZE = 64; // Assuming this based on context





    @Test
    public void testReadBits_LittleEndian_SingleByte() throws IOException {
        byte[] data = {(byte) 0xAB}; // 10101011
        BitInputStream bis = new BitInputStream(new ByteArrayInputStream(data), ByteOrder.LITTLE_ENDIAN);

        // Read 4 bits: should get 1011 (0xB) from the low end of 0xAB
        assertEquals(0xBL, bis.readBits(4));
        // Read next 4 bits: should get 1010 (0xA)
        assertEquals(0xAL, bis.readBits(4));
    }












}

