    public void testReadBits_LittleEndian_MultiByte() throws IOException {
        byte[] data = {(byte) 0x01, (byte) 0x02}; // 0x0201 in Little Endian
        BitInputStream bis = new BitInputStream(new ByteArrayInputStream(data), ByteOrder.LITTLE_ENDIAN);

        // 0x01 is 00000001. Read 8 bits.
