import static org.junit.Assert.assertEquals;

public class BitInputStream_readBits_TriageGen0Test {

    private static final int MAXIMUM_CACHE_SIZE = 64; // Assuming this based on context













    @Test
    public void testReadBits_EndOfStream() throws IOException {
        byte[] data = {(byte) 0xFF};
        BitInputStream bis = new BitInputStream(new ByteArrayInputStream(data), ByteOrder.BIG_ENDIAN);

        // Read 8 bits successfully
        assertEquals(0xFFL, bis.readBits(8));

        // Next read should trigger nextByte < 0 (EOF)
        // The method returns nextByte which is -1 when EOF is reached
        assertEquals(-1L, bis.readBits(1));
    }




}

package org.apache.commons.compress.utils;

import java.io.*;
import java.io.ByteArrayInputStream;
import java.io.Closeable;
import java.io.IOException;
import java.io.InputStream;
import java.math.*;
import java.nio.ByteOrder;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class BitInputStream_readBits_TriageGen0Test {

    private static final int MAXIMUM_CACHE_SIZE = 64; // Assuming this based on context















    @Test
    public void testReadBits_LargeCount_LittleEndian() throws IOException {
        // Testing the logic where bitsCachedSize >= count and involves shifting
        byte[] data = {(byte) 0xFF, (byte) 0xFF, (byte) 0xFF, (byte) 0xFF, (byte) 0xFF, (byte) 0xFF, (byte) 0xFF, (byte) 0x01};
        BitInputStream bis = new BitInputStream(new ByteArrayInputStream(data), ByteOrder.LITTLE_ENDIAN);

        // Read 56 bits
        long val = bis.readBits(56);
        assertEquals(0xFFFFFFFFFFFFFFL, val);

        // Read remaining 8 bits
        assertEquals(0x01L, bis.readBits(8));
    }


}

